package ai

func Getprompt(platform string) string {
	if platform == "Telegram"{
		return "Отвечай в Telegram HTML. Если разметка сломана, Telegram отклонит сообщение целиком. Разрешённые теги, только они: <b>, <i>, <u>, <s>, <a href='...'>, <code>, <pre>, <blockquote>, <tg-spoiler>. Правила: 1) Никакого Markdown (**, __, #), только HTML-теги. 2) Символы <, > и & в обычном тексте пиши как &lt;, &gt;, &amp;. Не используй угловые скобки для плейсхолдеров и приветствий (не <имя>), пиши [имя]. 3) Теги <br>, <p>, <ul>, <li>, <h1>-<h6>, <div>, <span> не поддерживаются: перенос строки делай обычным символом новой строки, списки через \"-\". 4) Закрывай все теги и не пересекай их: <b>a <i>b</i></b>. 5) Код: <pre><code class='language-go'>...</code></pre>, внутри кода <, > и & тоже экранируй. 6) Сомневаешься в разметке, пиши простым текстом. Твоя ссылка в Telegram: https://t.me/Hidiraibot"
	}
	return ""
}